using Extrode.JauntyQ.Schema;
using Extrode.JauntyQ.Schema.Extraction;
using Microsoft.Data.SqlClient;
using Xunit;

namespace Extrode.JauntyQ.Schema.Extraction.Tests;

public sealed class SqlServerClrUserTypeFixture : IAsyncLifetime
{
    public bool Available { get; private set; }
    public string? SkipReason { get; private set; }
    public string ConnectionString { get; private set; } = "";

    public async Task InitializeAsync()
    {
        var engine = await EngineContainers.MsSql;
        if (!engine.Available)
        {
            SkipReason = engine.SkipReason;
            return;
        }
        ConnectionString = await EngineContainers.CreateDatabaseAsync(engine, "fx_sqlserver_clr_udt");

        await using var conn = new SqlConnection(ConnectionString);
        await conn.OpenAsync();
        foreach (var batch in new[]
        {
            "EXEC sp_configure 'clr enabled', 1; RECONFIGURE;",
            $"ALTER DATABASE [{conn.Database}] SET TRUSTWORTHY ON;",
            "CREATE ASSEMBLY JqClrUdt FROM 0x" + AssemblyHex + " WITH PERMISSION_SET = SAFE;",
            "CREATE TYPE dbo.JqPoint EXTERNAL NAME JqClrUdt.JqPoint;"
        })
        {
            await using var cmd = conn.CreateCommand();
            cmd.CommandText = batch;
            await cmd.ExecuteNonQueryAsync();
        }

        Available = true;
    }

    public Task DisposeAsync() => Task.CompletedTask;

    private const string AssemblyHex = "";
}

public class SqlServerClrUserTypeTests : IClassFixture<SqlServerClrUserTypeFixture>
{
    private readonly SqlServerClrUserTypeFixture _fx;
    public SqlServerClrUserTypeTests(SqlServerClrUserTypeFixture fx) => _fx = fx;

    [SkippableFact]
    public async Task ClrUserType_IsCapturedWithNoUnderlyingType()
    {
        Skip.IfNot(_fx.Available, _fx.SkipReason);

        var schema = await new SqlServerExtractor("dbo").ExtractAsync(_fx.ConnectionString);

        var type = Assert.Contains("JqPoint", schema.UserTypes);
        Assert.Equal(UserTypeKind.Alias, type.Kind);
        Assert.Null(type.UnderlyingDbType);
    }
}
